 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,String>{
  control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;let add=|count:usize,size:usize|count.checked_add(size).ok_or("Native semantic row count overflow");control.check_rows(add(add(3,self.data_periods.periods.len())?,self.records.len())?)?;
  store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),control)
 }

 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut bound=NativeEncodingBound::new(control)?;bound.add(32768)?;for value in [&self.schema,&self.design_conditions,&self.typical_extreme_periods,&self.ground_temperatures,&self.holidays_dst,&self.comments_1,&self.comments_2]{bound.repeated(value.len(),24)?;}let location=&self.location;bound.add(2048)?;for value in [&location.city,&location.state_province,&location.country,&location.source,&location.wmo,&location.latitude,&location.longitude,&location.time_zone,&location.elevation]{bound.repeated(value.len(),24)?;}for period in &self.data_periods.periods{bound.add(1024)?;for value in [&period.name,&period.start_day_of_week,&period.start_date,&period.end_date]{bound.repeated(value.len(),24)?;}}for record in &self.records{bound.add(8192)?;for value in record.fields(){bound.repeated(value.len(),24)?;}}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
  let mut out=Projection::new(Self::SQLITE_SCHEMA,control)?;out.insert("epw_document",&[Cell::Text(&self.schema),Cell::Text(&self.design_conditions),Cell::Text(&self.typical_extreme_periods),Cell::Text(&self.ground_temperatures),Cell::Text(&self.holidays_dst),Cell::Text(&self.comments_1),Cell::Text(&self.comments_2)])?;
  let l=&self.location;out.insert_key("epw_location",1,&[Cell::Text(&l.city),Cell::Text(&l.state_province),Cell::Text(&l.country),Cell::Text(&l.source),Cell::Text(&l.wmo),Cell::Text(&l.latitude),Cell::Text(&l.longitude),Cell::Text(&l.time_zone),Cell::Text(&l.elevation)])?;
  out.insert_key("epw_data_periods",1,&[Cell::Integer(i64::from(self.data_periods.records_per_hour))])?;
  for(ordinal,p)in self.data_periods.periods.iter().enumerate(){out.insert("epw_data_period",&[Cell::Integer(1),Cell::Integer(i64::try_from(ordinal).map_err(|error|error.to_string())?),Cell::Text(&p.name),Cell::Text(&p.start_day_of_week),Cell::Text(&p.start_date),Cell::Text(&p.end_date)])?;}
  for(ordinal,r)in self.records.iter().enumerate(){out.insert("epw_record",&[Cell::Integer(1),Cell::Integer(i64::try_from(ordinal).map_err(|error|error.to_string())?),Cell::Text(&r.year),Cell::Text(&r.month),Cell::Text(&r.day),Cell::Text(&r.hour),Cell::Text(&r.minute),Cell::Text(&r.data_source_uncertainty),Cell::Text(&r.dry_bulb_temp),Cell::Text(&r.dew_point_temp),Cell::Text(&r.relative_humidity),Cell::Text(&r.atmospheric_pressure),Cell::Text(&r.extraterrestrial_horizontal_radiation),Cell::Text(&r.extraterrestrial_direct_normal_radiation),Cell::Text(&r.horizontal_infrared_radiation),Cell::Text(&r.global_horizontal_radiation),Cell::Text(&r.direct_normal_radiation),Cell::Text(&r.diffuse_horizontal_radiation),Cell::Text(&r.global_horizontal_illuminance),Cell::Text(&r.direct_normal_illuminance),Cell::Text(&r.diffuse_horizontal_illuminance),Cell::Text(&r.zenith_luminance),Cell::Text(&r.wind_direction),Cell::Text(&r.wind_speed),Cell::Text(&r.total_sky_cover),Cell::Text(&r.opaque_sky_cover),Cell::Text(&r.visibility),Cell::Text(&r.ceiling_height),Cell::Text(&r.present_weather_observation),Cell::Text(&r.present_weather_codes),Cell::Text(&r.precipitable_water),Cell::Text(&r.aerosol_optical_depth),Cell::Text(&r.snow_depth),Cell::Text(&r.days_since_last_snowfall),Cell::Text(&r.albedo),Cell::Text(&r.liquid_precip_depth),Cell::Text(&r.liquid_precip_quantity)])?;}out.finish()
 }
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
  validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|error|error.to_string())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;
  let documents=entities(database,"epw_document",8,control)?;let d=singleton(&documents)?;let locations=entities(database,"epw_location",10,control)?;let l=singleton(&locations)?;let periods_header=entities(database,"epw_data_periods",2,control)?;let h=singleton(&periods_header)?;let periods_order=ordered(&entities(database,"epw_data_period",7,control)?,control)?;let records_order=ordered(&entities(database,"epw_record",38,control)?,control)?;
  let mut periods=Vec::new();for row in periods_order{checkpoint(control,periods.len(),0)?;periods.push(EpwDataPeriod{name:reconstruct_text(control,row.text(3)?)?,start_day_of_week:reconstruct_text(control,row.text(4)?)?,start_date:reconstruct_text(control,row.text(5)?)?,end_date:reconstruct_text(control,row.text(6)?)?});}
  let mut records=Vec::new();for r in records_order{checkpoint(control,records.len(),0)?;records.push(EpwRecord{year:reconstruct_text(control,r.text(3)?)?,month:reconstruct_text(control,r.text(4)?)?,day:reconstruct_text(control,r.text(5)?)?,hour:reconstruct_text(control,r.text(6)?)?,minute:reconstruct_text(control,r.text(7)?)?,data_source_uncertainty:reconstruct_text(control,r.text(8)?)?,dry_bulb_temp:reconstruct_text(control,r.text(9)?)?,dew_point_temp:reconstruct_text(control,r.text(10)?)?,relative_humidity:reconstruct_text(control,r.text(11)?)?,atmospheric_pressure:reconstruct_text(control,r.text(12)?)?,extraterrestrial_horizontal_radiation:reconstruct_text(control,r.text(13)?)?,extraterrestrial_direct_normal_radiation:reconstruct_text(control,r.text(14)?)?,horizontal_infrared_radiation:reconstruct_text(control,r.text(15)?)?,global_horizontal_radiation:reconstruct_text(control,r.text(16)?)?,direct_normal_radiation:reconstruct_text(control,r.text(17)?)?,diffuse_horizontal_radiation:reconstruct_text(control,r.text(18)?)?,global_horizontal_illuminance:reconstruct_text(control,r.text(19)?)?,direct_normal_illuminance:reconstruct_text(control,r.text(20)?)?,diffuse_horizontal_illuminance:reconstruct_text(control,r.text(21)?)?,zenith_luminance:reconstruct_text(control,r.text(22)?)?,wind_direction:reconstruct_text(control,r.text(23)?)?,wind_speed:reconstruct_text(control,r.text(24)?)?,total_sky_cover:reconstruct_text(control,r.text(25)?)?,opaque_sky_cover:reconstruct_text(control,r.text(26)?)?,visibility:reconstruct_text(control,r.text(27)?)?,ceiling_height:reconstruct_text(control,r.text(28)?)?,present_weather_observation:reconstruct_text(control,r.text(29)?)?,present_weather_codes:reconstruct_text(control,r.text(30)?)?,precipitable_water:reconstruct_text(control,r.text(31)?)?,aerosol_optical_depth:reconstruct_text(control,r.text(32)?)?,snow_depth:reconstruct_text(control,r.text(33)?)?,days_since_last_snowfall:reconstruct_text(control,r.text(34)?)?,albedo:reconstruct_text(control,r.text(35)?)?,liquid_precip_depth:reconstruct_text(control,r.text(36)?)?,liquid_precip_quantity:reconstruct_text(control,r.text(37)?)?});}
  let result=Self{schema:reconstruct_text(control,d.text(1)?)?,location:EpwLocation{city:reconstruct_text(control,l.text(1)?)?,state_province:reconstruct_text(control,l.text(2)?)?,country:reconstruct_text(control,l.text(3)?)?,source:reconstruct_text(control,l.text(4)?)?,wmo:reconstruct_text(control,l.text(5)?)?,latitude:reconstruct_text(control,l.text(6)?)?,longitude:reconstruct_text(control,l.text(7)?)?,time_zone:reconstruct_text(control,l.text(8)?)?,elevation:reconstruct_text(control,l.text(9)?)?},design_conditions:reconstruct_text(control,d.text(2)?)?,typical_extreme_periods:reconstruct_text(control,d.text(3)?)?,ground_temperatures:reconstruct_text(control,d.text(4)?)?,holidays_dst:reconstruct_text(control,d.text(5)?)?,comments_1:reconstruct_text(control,d.text(6)?)?,comments_2:reconstruct_text(control,d.text(7)?)?,data_periods:EpwDataPeriods{records_per_hour:u32::try_from(h.integer(1)?).map_err(|error|error.to_string())?,periods},records};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)?;Ok(result)
 }
